CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_BILLING_MONTH_SEGMENT_REGION
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_BILLING at grain Date.FiscalYear, Date.MonthName, Date.Quarter, Customer.CustomerSegment, Location.Region, Date.MonthNumber; covers 29.73% of weighted demand (4 clusters); est. 240 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.MONTH_NAME,
       d1.QUARTER,
       c3.CUSTOMER_SEGMENT,
       l4.REGION,
       d1.MONTH_NUMBER,
       SUM(f.BILL_AMOUNT) AS BILL_AMOUNT,
       SUM(f.DEMAND_CHARGE) AS DEMAND_CHARGE,
       SUM(f.ENERGY_CHARGE) AS ENERGY_CHARGE,
       SUM(f.TAX_AMOUNT) AS TAX_AMOUNT,
       SUM(f.TOTAL_BILL_WITH_TAX) AS TOTAL_BILL_WITH_TAX,
       COUNT(*) AS BILLING_COUNT
FROM CORE.FCT_BILLING f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_METER m2 ON f.METER_ID = m2.METER_ID
JOIN CORE.DIM_CUSTOMER c3 ON m2.CUSTOMER_ID = c3.CUSTOMER_ID
JOIN CORE.DIM_LOCATION l4 ON m2.LOCATION_ID = l4.LOCATION_ID
GROUP BY ALL;

